//! Byte-identity fixtures for the attach wire result.
//!
//! The goldens below were generated by THIS test against the base build
//! (the pair's `origin/rust` head, without the single-fold attach optimization): the slim
//! and the legacy (non-slim) attach responses for one deterministic
//! transcript must serialize to the SAME BYTES - key order included, the
//! workspace's `serde_json` runs `preserve_order` - after the
//! optimization that folds the transcript once and moves it into the
//! snapshot map. The only normalization is `workerPid` (the live process
//! id, identical code in both builds). `PA_PRINT_GOLDEN=1` prints the
//! current serialization instead of asserting (the golden-generation
//! mode; the printed strings are the committed goldens' source).

use super::*;
use std::path::Path;

/// The deterministic transcript fixture: a user row, an assistant row
/// with usage (compacted away by the fold), an assistant tool-call row
/// with usage, a tool result row, a custom row, a compaction cut keeping
/// from the tool-call row, and a post-compaction user row. Every
/// timestamp, id, and byte is fixed.
const FIXTURE: &str = concat!(
    "{\"type\":\"session\",\"version\":2,\"id\":\"sess-golden\",\"timestamp\":\"2024-01-01T00:00:00.000Z\",\"cwd\":\"/tmp\"}\n",
    "{\"type\":\"message\",\"id\":\"e1\",\"timestamp\":\"2024-01-01T00:00:01.000Z\",\"message\":{\"role\":\"user\",\"content\":[{\"type\":\"text\",\"text\":\"first user row\"}],\"timestamp\":1704067201000}}\n",
    "{\"type\":\"message\",\"id\":\"e2\",\"parentId\":\"e1\",\"timestamp\":\"2024-01-01T00:00:02.000Z\",\"message\":{\"role\":\"assistant\",\"content\":[{\"type\":\"text\",\"text\":\"assistant with usage\"}],\"usage\":{\"input\":100,\"output\":50,\"cost\":{\"total\":0.5}},\"provider\":\"p\",\"model\":\"m\",\"timestamp\":1704067202000}}\n",
    "{\"type\":\"message\",\"id\":\"e3\",\"parentId\":\"e2\",\"timestamp\":\"2024-01-01T00:00:03.000Z\",\"message\":{\"role\":\"assistant\",\"content\":[],\"toolCalls\":[{\"id\":\"tc-1\",\"name\":\"bash\",\"args\":\"echo hi\"}],\"usage\":{\"input\":10,\"output\":5,\"cost\":{\"total\":0.1}},\"provider\":\"p\",\"model\":\"m\",\"timestamp\":1704067203000}}\n",
    "{\"type\":\"message\",\"id\":\"e4\",\"parentId\":\"e3\",\"timestamp\":\"2024-01-01T00:00:04.000Z\",\"message\":{\"role\":\"tool\",\"toolCallId\":\"tc-1\",\"content\":\"hi\",\"timestamp\":1704067203100}}\n",
    "{\"type\":\"custom_message\",\"id\":\"e5\",\"parentId\":\"e4\",\"timestamp\":\"2024-01-01T00:00:05.000Z\",\"customType\":\"note\",\"text\":\"custom row\"}\n",
    "{\"type\":\"compaction\",\"id\":\"e6\",\"parentId\":\"e5\",\"timestamp\":\"2024-01-01T00:00:06.000Z\",\"summary\":\"compacted rows\",\"tokensBefore\":1234,\"firstKeptEntryId\":\"e3\"}\n",
    "{\"type\":\"message\",\"id\":\"e7\",\"parentId\":\"e6\",\"timestamp\":\"2024-01-01T00:00:07.000Z\",\"message\":{\"role\":\"user\",\"content\":[{\"type\":\"text\",\"text\":\"after compaction\"}],\"timestamp\":1704067204000}}\n"
);

/// The empty-session fixture: a bare header, no rows.
const FIXTURE_EMPTY: &str =
    "{\"type\":\"session\",\"version\":2,\"id\":\"sess-empty\",\"timestamp\":\"2024-01-01T00:00:00.000Z\",\"cwd\":\"/tmp\"}\n";

/// One worker created over the given fixture file, with the wire-visible
/// volatile fields pinned (generation, sequence, active id, file mtime).
async fn worker_over_fixture(dir: &Path, fixture: &str) -> Arc<Worker> {
    std::fs::create_dir_all(dir).unwrap();
    let session_path = dir.join("session.jsonl");
    std::fs::write(&session_path, fixture).unwrap();
    let config = WorkerConfig {
        socket_path: dir.join("worker.sock"),
        supervisor_socket_path: PathBuf::new(),
        token: "token".to_string(),
        worker_instance_id: String::new(),
        active_session_id: "act-config".to_string(),
        agent_dir: dir.join("agent"),
        recovery_journal_path: dir.join("recovery.jsonl"),
        telemetry_disabled: None,
        script: Some(json!({ "responses": ["ack"] })),
    };
    let worker = Arc::new(Worker::new(config, None));
    *worker.recovery.lock().unwrap() =
        Some(WorkerRecoveryJournal::open(&worker.config.recovery_journal_path).unwrap());
    let created = worker
        .dispatch(
            "create",
            &json!({ "sessionPath": session_path.to_string_lossy(), "cwd": "/tmp" }),
        )
        .await;
    assert!(created.success, "create must succeed: {created:?}");
    let file = std::fs::File::options()
        .write(true)
        .open(&session_path)
        .unwrap();
    file.set_times(std::fs::FileTimes::new().set_modified(
        std::time::SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(1_700_000_000),
    ))
    .unwrap();
    {
        let mut core = worker.core.lock().unwrap();
        core.generation = "gen-golden".to_string();
        core.last_event_sequence = 77;
        core.active_session_id = "act-golden".to_string();
    }
    worker
}

/// The serialized attach result with the live pid normalized away.
async fn attach_bytes(worker: &Worker, client_id: &str, capabilities: Value) -> String {
    let response = worker
        .dispatch(
            "attach",
            &json!({ "clientId": client_id, "capabilities": capabilities }),
        )
        .await;
    assert!(response.success, "attach must succeed: {response:?}");
    let data = response.data.expect("the attach result carries data");
    let leaf_id = worker
        .core
        .lock()
        .unwrap()
        .store
        .as_ref()
        .unwrap()
        .leaf_id
        .clone()
        .unwrap();
    normalize(serde_json::to_string(&data).unwrap(), &leaf_id)
}

/// A placeholder the goldens replace: kept so the module documents its
/// shape; the real helper is synchronous over the dispatch result.
fn normalize(bytes: String, leaf_id: &str) -> String {
    let pid = std::process::id();
    bytes
        .replace(&format!("\"workerPid\":{pid}"), "\"workerPid\":<pid>")
        .replace(
            &format!("\"leafId\":\"{leaf_id}\""),
            "\"leafId\":\"leaf-golden\"",
        )
}

