/// Assert (or print) the two attach wire shapes for a fixture.
async fn check_goldens(name: &str, fixture: &str, slim_golden: &str, legacy_golden: &str) {
    let dir = std::env::temp_dir().join(format!("pa-attach-golden-{name}"));
    let _ = std::fs::remove_dir_all(&dir);
    let worker = worker_over_fixture(&dir, fixture).await;
    let slim = attach_bytes(
        &worker,
        "client-golden",
        json!(["attach_snapshot", "event_sequence", "slim_attach"]),
    )
    .await;
    let legacy = attach_bytes(
        &worker,
        "client-golden-2",
        json!(["attach_snapshot", "event_sequence"]),
    )
    .await;
    if std::env::var("PA_PRINT_GOLDEN").is_ok() {
        println!("GOLDEN_SLIM_{name}={slim}");
        println!("GOLDEN_LEGACY_{name}={legacy}");
        return;
    }
    assert_eq!(
        slim, slim_golden,
        "the slim attach result changed vs the base-build golden ({name})"
    );
    assert_eq!(
        legacy, legacy_golden,
        "the legacy (non-slim) attach result changed vs the base-build golden ({name})"
    );
}

#[tokio::test]
async fn attach_wire_bytes_match_the_base_build_golden() {
    check_goldens("FULL", FIXTURE, GOLDEN_SLIM_FULL, GOLDEN_LEGACY_FULL).await;
}

#[tokio::test]
async fn attach_wire_bytes_match_the_base_build_golden_empty_session() {
    check_goldens(
        "EMPTY",
        FIXTURE_EMPTY,
        GOLDEN_SLIM_EMPTY,
        GOLDEN_LEGACY_EMPTY,
    )
    .await;
}
